mapper.select:
      select
      count_tb  ,
      money_tb ,
      ybw_tb ,
      ybyq_tb ,
      ybwq_tb ,
      wq_tb ,
      count_zb ,
      money_zb ,
      ybw_zb ,
      ybyq_zb ,
      ybwq_zb,
      wq_zb
      from (
      select sum(t1.ybw_tb+t1.ybyq_tb+t1.ybwq_tb+wq_tb) as count_tb,
      sum(t1.buy_budget_money) as money_tb,
      sum(ybw_tb) as ybw_tb,
      sum(ybyq_tb) as ybyq_tb,
      sum(ybwq_tb) as ybwq_tb,
      sum(wq_tb) as wq_tb from
      (select
      a.buy_budget_money,
      if(a.buy_budget_money>100,1,0) as ybw_tb,
      if(a.buy_budget_money>=100 and a.buy_budget_money >1000 ,1,0) as ybyq_tb,
      if(a.buy_budget_money>=1000 and a.buy_budget_money >5000 ,1,0) as ybwq_tb,
      if(a.buy_budget_money>=5000,1,0) as wq_tb
      from  topp_bid_new a inner join  topp_opportunity b
      on a.opportunity_code =b.id_ inner  join zqzt_sys_user c
      on b.designer =c.user_id
      inner join zqzt_sys_dept d on c.dept_id = d.dept_id
      where d.dept_id  in (
      select dept_id from zqzt_sys_dept where dept_id = #{tempDeptId}
      union
      select t.dept_id from (select * from zqzt_sys_dept where parent_id is not null) t,
      (select @parent_id := #{tempDeptId}) pd
      where FIND_IN_SET(parent_id,@parent_id) > 0
      and @parent_id := CONCAT(@parent_id,',',dept_id)
      )and a.is_sign='0'

         and a.buy_budget_money >= #{minCgAmount}


         and a.buy_budget_money < #{maxCgAmount}



          and a.sign_money >= #{minYjAmount}


          and a.sign_money < #{maxYjAmount}



          and b.expect_count_money >= #{minYjAmount}


          and b.expect_count_money <  #{maxYjAmount}



          and a.bid_body in

              #{item}



          and a.competition_condition in

              #{item}



          and a.project_type in

              #{item}



          and a.result = #{bidResult}


          and b.unicom_type in

              #{item}



          and a.ict_profit>= #{minMll}


          and a.ict_profit <= #{maxMll}


              and a.open_bid_time >= #{startTime}


              and a.open_bid_time <= #{endTime}

)t1 )a
      left join

      (select sum(t1.ybw_zb+t1.ybyq_zb+t1.ybwq_zb+wq_zb) as count_zb,
      sum(t1.sign_money) as money_zb,
      sum(ybw_zb) as ybw_zb,
      sum(ybyq_zb) as ybyq_zb,
      sum(ybwq_zb) as ybwq_zb,
      sum(wq_zb) as wq_zb from
      (select
      a.sign_money,
      if(a.sign_money >100,1,0) as ybw_zb,
      if(a.sign_money>=100 and a.sign_money >1000 ,1,0) as ybyq_zb,
      if(a.sign_money>=1000 and a.sign_money >5000 ,1,0) as ybwq_zb,
      if(a.sign_money>=5000,1,0) as wq_zb
      from  topp_bid_new a inner join  topp_opportunity b
      on a.opportunity_code =b.id_ inner  join zqzt_sys_user c
      on b.designer =c.user_id
      inner join zqzt_sys_dept d on c.dept_id = d.dept_id
      where d.dept_id  in  (
      select dept_id from zqzt_sys_dept where dept_id = #{tempDeptId}
      union
      select t.dept_id from (select * from zqzt_sys_dept where parent_id is not null) t,
      (select @parent_id := #{tempDeptId}) pd
      where FIND_IN_SET(parent_id,@parent_id) > 0
      and @parent_id := CONCAT(@parent_id,',',dept_id)
      ) and a.is_sign='0' and result='match_bid'

          and a.buy_budget_money >= #{minCgAmount}


          and a.buy_budget_money < #{maxCgAmount}



          and a.sign_money >= #{minYjAmount}


          and a.sign_money < #{maxYjAmount}



          and b.expect_count_money >= #{minYjAmount}


          and b.expect_count_money < #{maxYjAmount}



          and a.bid_body in

              #{item}



          and a.competition_condition in

              #{item}



          and a.project_type in

              #{item}



          and a.result = #{bidResult}


          and b.unicom_type in

              #{item}



          and a.ict_profit>= #{minMll}


          and a.ict_profit <= #{maxMll}


          and a.open_bid_time >= #{startTime}


          and a.open_bid_time <= #{endTime}

      )t1)b on 1=1

select
a.nick_name as user_name,
count_tb  ,
money_tb ,
ybw_tb ,
ybyq_tb ,
ybwq_tb ,
wq_tb ,
count_zb ,
money_zb ,
ybw_zb ,
ybyq_zb ,
ybwq_zb,
wq_zb,
gxed_zb
from (
SELECT
t1.nick_name,
SUM(t1.ybw_tb + t1.ybyq_tb + t1.ybwq_tb + t1.wq_tb) AS count_tb,
SUM(t1.buy_budget_money) AS money_tb,
SUM(t1.ybw_tb) AS ybw_tb,
SUM(t1.ybyq_tb) AS ybyq_tb,
SUM(t1.ybwq_tb) AS ybwq_tb,
SUM(t1.wq_tb) AS wq_tb
FROM (
SELECT
d.nick_name,
a.buy_budget_money,
CASE WHEN a.buy_budget_money < 100 THEN 1 ELSE 0 END AS ybw_tb,
CASE WHEN a.buy_budget_money BETWEEN 100 AND 999 THEN 1 ELSE 0 END AS ybyq_tb,
CASE WHEN a.buy_budget_money BETWEEN 1000 AND 4999 THEN 1 ELSE 0 END AS ybwq_tb,
CASE WHEN a.buy_budget_money >= 5000 THEN 1 ELSE 0 END AS wq_tb
FROM topp_bid_new a
INNER JOIN topp_opportunity b ON a.opportunity_code = b.id_
inner join topp_member c on b.id_ = c.project_id
INNER JOIN zqzt_sys_user d ON c .member_id = d.user_id
INNER JOIN zqzt_sys_dept e ON d.dept_id = e.dept_id
WHERE e.dept_id = #{deptId}
AND a.is_sign = '0'

    and a.buy_budget_money >= #{minCgAmount}


    and a.buy_budget_money < #{maxCgAmount}



    and a.sign_money >= #{minYjAmount}


    and a.sign_money < #{maxYjAmount}



    and b.expect_count_money >= #{minYjAmount}


    and b.expect_count_money <  #{maxYjAmount}



    and a.bid_body in

        #{item}



    and a.competition_condition in

        #{item}



    and a.project_type in

        #{item}



    and a.result = #{bidResult}


    and b.unicom_type in

        #{item}



    and a.ict_profit>= #{minMll}


    and a.ict_profit <= #{maxMll}


    and a.open_bid_time >= #{startTime}


    and a.open_bid_time <= #{endTime}

) t1
GROUP BY t1.nick_name )a
left join

( SELECT
t1.nick_name,
SUM(t1.ybw_zb + t1.ybyq_zb + t1.ybwq_zb + t1.wq_zb) AS count_zb,
SUM(t1.match_bid_money) AS money_zb,
SUM(t1.ybw_zb) AS ybw_zb,
SUM(t1.ybyq_zb) AS ybyq_zb,
SUM(t1.ybwq_zb) AS ybwq_zb,
SUM(t1.wq_zb) AS wq_zb,
sum(t1.match_bid_money * t1.contribution) as gxed_zb
FROM (
SELECT
d.nick_name,
a.match_bid_money,
CASE WHEN a.match_bid_money < 100 THEN 1 ELSE 0 END AS ybw_zb,
CASE WHEN a.match_bid_money BETWEEN 100 AND 999 THEN 1 ELSE 0 END AS ybyq_zb,
CASE WHEN a.match_bid_money BETWEEN 1000 AND 4999 THEN 1 ELSE 0 END AS ybwq_zb,
CASE WHEN a.match_bid_money >= 5000 THEN 1 ELSE 0 END AS wq_zb,
c.contribution
FROM topp_bid_new a
INNER JOIN topp_opportunity b ON a.opportunity_code = b.id_
inner join topp_bid_new_score c on a.id=c.topp_bid_new_id
inner join topp_member f on b.id_ = f.project_id
INNER JOIN zqzt_sys_user d ON f .member_id = d.user_id
INNER JOIN zqzt_sys_dept e ON d.dept_id = e.dept_id
WHERE  e.dept_id =#{deptId}
and a.is_sign='0' and a.result='match_bid'

    and a.buy_budget_money >= #{minCgAmount}


    and a.buy_budget_money < #{maxCgAmount}



    and a.sign_money >= #{minYjAmount}


    and a.sign_money < #{maxYjAmount}



    and b.expect_count_money >= #{minYjAmount}


    and b.expect_count_money < #{maxYjAmount}



    and a.bid_body in

        #{item}



    and a.competition_condition in

        #{item}



    and a.project_type in

        #{item}



    and a.result = #{bidResult}


    and b.unicom_type in

        #{item}



    and a.ict_profit>= #{minMll}


    and a.ict_profit <= #{maxMll}


    and a.open_bid_time >= #{startTime}


    and a.open_bid_time <= #{endTime}

)t1 GROUP BY t1.nick_name)b on a.nick_name=b.nick_name
